  private updateGreeting(): void {
    const hour = new Date().getHours();
    if (hour < 6) {
      this.greetingText = '夜深了';
    } else if (hour < 12) {
      this.greetingText = '早上好';
    } else if (hour < 14) {
      this.greetingText = '中午好';
    } else if (hour < 18) {
      this.greetingText = '下午好';
    } else if (hour < 22) {
      this.greetingText = '晚上好';
    } else {
      this.greetingText = '夜深了';
