    this.restorePhase = RestorePhase.FIRST_CONFIRM;
    try {
      try {
        const firstConfirm: promptAction.ShowDialogSuccessResponse = await promptAction.showDialog({
          title: '从云端恢复',
          message: '⚠️ 警告：此操作将从云端下载备份并覆盖本地数据，本地未同步的学习记录将丢失。\\n\\n确定要继续吗？',
