            { text: '取消', color: String(this.colors.TEXT_SECONDARY) },
            { text: '继续', color: String(this.colors.WARNING) }
          ]
        });
        if (firstConfirm.index !== 1) return;
      } catch {
        return;
      }

      this.restorePhase = RestorePhase.PREPARING;
      this.webdavBackupResult = '正在准备云端恢复...';
