        this.webdavBackupResult = '⚠️ 保存设置失败，请先保存 WebDAV 设置';
        promptAction.showToast({ message: '保存设置失败', duration: 1200 });
        return;
      }

      this.restorePhase = RestorePhase.DOWNLOADING;
      this.webdavBackupResult = '正在下载云端备份...';
